class Solution:
    def longestNiceSubstring(self, s: str) -> str:
        n = len(s)
        best_start, best_len = 0, 0
        for i in range(n):
            lower = upper = 0
            for j in range(i, n):
                ch = ord(s[j])
                if ch >= 97:
                    lower |= 1 << (ch - 97)
                else:
                    upper |= 1 << (ch - 65)
                if lower == upper and j - i + 1 > best_len:
                    best_start, best_len = i, j - i + 1
        return s[best_start:best_start + best_len]

