class Solution {
public:
    string longestNiceSubstring(string s) {
        int n = s.size(), bi = 0, bl = 0;
        for (int i = 0; i < n; i++) {
            int lower = 0, upper = 0;
            for (int j = i; j < n; j++) {
                char c = s[j];
                if (islower(c)) lower |= 1 << (c - 'a');
                else upper |= 1 << (c - 'A');
                if (lower == upper && j - i + 1 > bl) {
                    bi = i;
                    bl = j - i + 1;
                }
            }
        }
        return s.substr(bi, bl);
    }
};

